export type V1014OffshoreMarineBand = 'shore_idle' | 'lease_active' | 'export_corridor' | 'marine_leader';

export type V1014DemandResponseBand = 'dormant' | 'pilot_vpp' | 'orchestrated' | 'grid_shield';

